B.aXt=s(["\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0639\u0644\u0649 \u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \xab%1\xbb","\u0646\u0627\u06a9\u0631\u06ce\u062a \u0644\u06d5\u0633\u06d5\u0631 \u062d\u0633\u0627\u0628\u06cc \u06af\u0631\u0648\u067e\u06cc \xab%1\xbb \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u0631\u06ce\u062a","\u0646\u0627\u0628\u06cc\u062a \u0644 \u0633\u06d5\u0631 \u062d\u0633\u0627\u0628\u06ce \u06af\u0631\u0648\u067e\u06ce \xab%1\xbb \u062a\u06c6\u0645\u0627\u0631 \u0628\u06cc\u062a"],t.s)
B.b5z=s(["\u0627\u0644\u062d\u0633\u0627\u0628 \xab%1\xbb \u063a\u064a\u0631 \u0641\u0639\u0651\u0627\u0644","\u062d\u0633\u0627\u0628\u06cc \xab%1\xbb \u0646\u0627\u0686\u0627\u0644\u0627\u06a9\u06d5","\u062d\u0633\u0627\u0628\u06ce \xab%1\xbb \u0646\u06d5\u0686\u0627\u0644\u0627\u06a9\u06d5"],t.s)
B.aX9=s(["\u0627\u0644\u062d\u0633\u0627\u0628 \xab%1\xbb \u064a\u0642\u0628\u0644 %2 \u0641\u0642\u0637","\u062d\u0633\u0627\u0628\u06cc \xab%1\xbb \u062a\u06d5\u0646\u0647\u0627 %2 \u0648\u06d5\u0631\u062f\u06d5\u06af\u0631\u06ce\u062a","\u062d\u0633\u0627\u0628\u06ce \xab%1\xbb \u062a\u0646\u06ce %2 \u0648\u06d5\u0631\u062f\u06af\u0631\u06cc\u062a"],t.s)
B.aV8=s(["\u0627\u0644\u0635\u0646\u062f\u0648\u0642 \xab%1\xbb \u064a\u0642\u0628\u0644 %2 \u0641\u0642\u0637","\u0633\u0646\u062f\u0648\u0642\u06cc \xab%1\xbb \u062a\u06d5\u0646\u0647\u0627 %2 \u0648\u06d5\u0631\u062f\u06d5\u06af\u0631\u06ce\u062a","\u0633\u0646\u062f\u0648\u0642\u06ce \xab%1\xbb \u062a\u0646\u06ce %2 \u0648\u06d5\u0631\u062f\u06af\u0631\u06cc\u062a"],t.s)
B.aYt=s(["\u064a\u062d\u062a\u0627\u062c \u0627\u0644\u0633\u0646\u062f \u0625\u0644\u0649 \u0633\u0637\u0631\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644","\u0633\u06d5\u0646\u06d5\u062f \u0644\u0627\u0646\u06cc\u06a9\u06d5\u0645 \u062f\u0648\u0648 \u062f\u06ce\u0695\u06cc \u067e\u06ce\u0648\u06cc\u0633\u062a\u06d5","\u0633\u06d5\u0646\u06d5\u062f \u067e\u06ce\u062a\u06a4\u06cc \u0628 \u062f\u0648\u0648 \u0695\u06ce\u0632\u0627\u0646 \u0647\u06d5\u06cc\u06d5"],t.s)
B.aVa=s(["\u0643\u0644 \u0633\u0637\u0631 \u064a\u062d\u062a\u0627\u062c \u0645\u0628\u0644\u063a\u0627\u064b \u0645\u062f\u064a\u0646\u0627\u064b \u0623\u0648 \u062f\u0627\u0626\u0646\u0627\u064b","\u0647\u06d5\u0631 \u062f\u06ce\u0695\u06ce\u06a9 \u0628\u0695\u06ce\u06a9\u06cc \u0645\u06d5\u062f\u06cc\u0646 \u06cc\u0627\u0646 \u062f\u0627\u0626\u06cc\u0646\u06cc \u067e\u06ce\u0648\u06cc\u0633\u062a\u06d5","\u0647\u06d5\u0631 \u0695\u06ce\u0632\u06d5\u06a9 \u067e\u06ce\u062a\u06a4\u06cc \u0628 \u0628\u0695\u06d5\u06a9\u06ce \u0645\u06d5\u062f\u06cc\u0646 \u06cc\u0627\u0646 \u062f\u0627\u0626\u06cc\u0646 \u0647\u06d5\u06cc\u06d5"],t.s)
