B.aTW=s(["\u0627\u0644\u0633\u0646\u062f \u063a\u064a\u0631 \u0645\u062a\u0648\u0627\u0632\u0646 \u0628\u0640 %1 (\u0627\u0644\u0641\u0631\u0642 %2)","\u0633\u06d5\u0646\u06d5\u062f\u06d5\u06a9\u06d5 \u0628\u06d5 %1 \u0647\u0627\u0648\u0633\u06d5\u0646\u06af \u0646\u06cc\u06cc\u06d5 (\u062c\u06cc\u0627\u0648\u0627\u0632\u06cc %2)","\u0633\u06d5\u0646\u06d5\u062f \u0628 %1 \u0647\u06d5\u06a4\u0633\u06d5\u0646\u06af \u0646\u06cc\u0646\u06d5 (\u062c\u0648\u062f\u0627\u0647\u06cc %2)"],t.s)
B.b6u=s(["\u0633\u0646\u062f \u0627\u0644\u0642\u0628\u0636 \u064a\u062c\u0628 \u0623\u0646 \u064a\u064f\u062f\u062e\u0644 \u0627\u0644\u0645\u0627\u0644 \u0625\u0644\u0649 \u0635\u0646\u062f\u0648\u0642 \u0623\u0648 \u062d\u0633\u0627\u0628 \u0645\u0643\u062a\u0628","\u0648\u06d5\u0631\u06af\u0631\u062a\u0646 \u062f\u06d5\u0628\u06ce\u062a \u067e\u0627\u0631\u06d5 \u0628\u062e\u0627\u062a\u06d5 \u0633\u0646\u062f\u0648\u0642 \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06cc \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06ce\u06a9","\u0648\u06d5\u0631\u06af\u0631\u062a\u0646 \u062f\u06a4\u06ce\u062a \u067e\u0627\u0631\u06d5\u06cc \u0628\u06ce\u062e\u06cc\u062a\u06d5 \u0633\u0646\u062f\u0648\u0642\u06d5\u06a9\u06ce \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06ce \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06d5\u06a9\u06ce"],t.s)
B.b6p=s(["\u0633\u0646\u062f \u0627\u0644\u0635\u0631\u0641 \u064a\u062c\u0628 \u0623\u0646 \u064a\u064f\u062e\u0631\u062c \u0627\u0644\u0645\u0627\u0644 \u0645\u0646 \u0635\u0646\u062f\u0648\u0642 \u0623\u0648 \u062d\u0633\u0627\u0628 \u0645\u0643\u062a\u0628","\u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u062f\u06d5\u0628\u06ce\u062a \u067e\u0627\u0631\u06d5 \u0644\u06d5 \u0633\u0646\u062f\u0648\u0642 \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06cc \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06ce\u06a9 \u062f\u06d5\u0631\u0628\u0647\u06ce\u0646\u06ce\u062a","\u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u062f\u06a4\u06ce\u062a \u067e\u0627\u0631\u06d5\u06cc \u0698 \u0633\u0646\u062f\u0648\u0642\u06d5\u06a9\u06ce \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06ce \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06d5\u06a9\u06ce \u062f\u06d5\u0631\u0628\u06ce\u062e\u06cc\u062a"],t.s)
B.aSE=s(["\u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0648\u0627\u0644\u0635\u0631\u0641 \u064a\u0646\u0642\u0644\u0627\u0646 \u0627\u0644\u0645\u0627\u0644 \u0628\u064a\u0646 \u0627\u0644\u0635\u0646\u0627\u062f\u064a\u0642 \u0648\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0645\u0643\u0627\u062a\u0628 \u0641\u0642\u0637","\u06af\u0648\u0627\u0633\u062a\u0646\u06d5\u0648\u06d5 \u0648 \u06af\u06c6\u0695\u06cc\u0646\u06d5\u0648\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u067e\u0627\u0631\u06d5 \u0644\u06d5 \u0646\u06ce\u0648\u0627\u0646 \u0633\u0646\u062f\u0648\u0642 \u0648 \u062d\u0633\u0627\u0628\u06cc \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u06af\u0648\u0627\u0632\u0646\u06d5\u0648\u06d5","\u06a4\u06d5\u06af\u0648\u0647\u0627\u0633\u062a\u0646 \u0648 \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646 \u062a\u0646\u06ce \u067e\u0627\u0631\u06d5\u06cc \u062f \u0646\u0627\u06a4\u0628\u06d5\u0631\u0627 \u0633\u0646\u062f\u0648\u0642 \u0648 \u062d\u0633\u0627\u0628\u06ce\u0646 \u0645\u06d5\u06a9\u062a\u06d5\u0628\u0627\u0646 \u062f\u0627 \u06a4\u06d5\u062f\u06af\u0648\u0647\u06ce\u0632\u0646"],t.s)
B.b5k=s(["\u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u064a\u062a\u063a\u064a\u0631 \u0641\u0642\u0637 \u0639\u0628\u0631 \u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0627\u0644\u0645\u062e\u0632\u0646 (\u0631\u0635\u064a\u062f \u0623\u0648\u0644 \u0627\u0644\u0645\u062f\u0629\u060c \u0627\u0644\u0634\u0631\u0627\u0621\u060c \u0627\u0644\u0628\u064a\u0639)","\u062d\u0633\u0627\u0628\u06cc \u06a9\u0627\u06b5\u0627\u06cc \u06a9\u06c6\u06af\u0627 \u062a\u06d5\u0646\u0647\u0627 \u0628\u06d5 \u0633\u06d5\u0646\u06d5\u062f\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06c6\u06af\u0627 \u062f\u06d5\u06af\u06c6\u0695\u06ce\u062a (\u06a9\u0627\u06b5\u0627\u06cc \u0633\u06d5\u0631\u06d5\u062a\u0627\u060c \u06a9\u0695\u06cc\u0646\u060c \u0641\u0631\u06c6\u0634\u062a\u0646)","\u062d\u0633\u0627\u0628\u06ce \u06a9\u0627\u0644\u0627\u06cc\u06ce\u0646 \u06a9\u06c6\u06af\u06d5\u0647\u06ce \u062a\u0646\u06ce \u0628 \u0633\u06d5\u0646\u06d5\u062f\u06ce\u0646 \u06a9\u06c6\u06af\u06d5\u0647\u06ce \u062f\u0647\u06ce\u062a\u06d5 \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646 (\u06a9\u0627\u0644\u0627\u06cc\u06ce\u0646 \u062f\u06d5\u0633\u062a\u067e\u06ce\u06a9\u06ce\u060c \u06a9\u0695\u06cc\u0646\u060c \u0641\u0631\u06c6\u062a\u0646)"],t.s)
