B.aYh=s(["\u0627\u0644\u0645\u064f\u0631\u062c\u064e\u0639 \u0645\u0646 \xab%1\xbb (%2) \u0623\u0643\u062b\u0631 \u0645\u0645\u0627 \u0641\u064a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u0631\u0642\u0645 %3 (%4)","\xab%1\xbb \u0632\u06cc\u0627\u062a\u0631 \u06af\u06d5\u0695\u06ce\u0646\u0631\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5 (%2) \u0644\u06d5\u0648\u06d5\u06cc \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u0698\u0645\u0627\u0631\u06d5 %3 \u0647\u06d5\u06cc\u0628\u0648\u0648 (%4)","\xab%1\xbb \u067e\u062a\u0631 \u0647\u0627\u062a\u06cc\u06cc\u06d5 \u0632\u06a4\u0695\u0627\u0646\u062f\u0646 (%2) \u0698 \u06cc\u0627 \u067e\u0633\u0648\u0648\u0644\u0627 \u0698\u0645\u0627\u0631\u06d5 %3 \u0647\u06d5\u06cc (%4)"],t.s)
B.aUX=s(["\u0627\u0644\u0637\u0644\u0628 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f","\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06d5 \u0646\u06d5\u062f\u06c6\u0632\u0631\u0627\u06cc\u06d5\u0648\u06d5","\u062f\u0627\u062e\u0648\u0627\u0632\u06cc \u0646\u06d5\u0647\u0627\u062a\u06d5 \u062f\u06cc\u062a\u0646"],t.s)
B.aYi=s(["\u064a\u0645\u0643\u0646 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u0645\u0639\u0644\u0651\u0642 \u0641\u0642\u0637","\u062a\u06d5\u0646\u0647\u0627 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0686\u0627\u0648\u06d5\u0695\u0648\u0627\u0646 \u062f\u06d5\u06af\u06c6\u0695\u062f\u0631\u06ce\u062a","\u062a\u0646\u06ce \u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u0686\u0627\u06a4\u06d5\u0695\u06ce \u062f\u0647\u06ce\u062a\u06d5 \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646"],t.s)
B.b1d=s(["\u0627\u0644\u0637\u0644\u0628 \u0631\u0642\u0645 %1 \u0644\u064a\u0633 \u0645\u0639\u0644\u0651\u0642\u0627\u064b","\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0698\u0645\u0627\u0631\u06d5 %1 \u0686\u0627\u0648\u06d5\u0695\u0648\u0627\u0646 \u0646\u06cc\u06cc\u06d5","\u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u0698\u0645\u0627\u0631\u06d5 %1 \u0646\u06d5 \u0686\u0627\u06a4\u06d5\u0695\u06ce\u06cc\u06d5"],t.s)
B.aXU=s(["\u0644\u0644\u0637\u0644\u0628 \u0631\u0642\u0645 %1 \u0641\u0627\u062a\u0648\u0631\u0629 \u0631\u0642\u0645 %2 \u0623\u0635\u0644\u0627\u064b","\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0698\u0645\u0627\u0631\u06d5 %1 \u067e\u06ce\u0634\u062a\u0631 \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u0698\u0645\u0627\u0631\u06d5 %2 \u06cc \u0647\u06d5\u06cc\u06d5","\u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u0698\u0645\u0627\u0631\u06d5 %1 \u0698 \u0628\u06d5\u0631\u06cc \u0646\u0648\u06a9\u06d5 \u067e\u0633\u0648\u0648\u0644\u0627 \u0698\u0645\u0627\u0631\u06d5 %2 \u0647\u06d5\u06cc\u06d5"],t.s)
B.b1M=s(["\u0644\u0644\u0637\u0644\u0628 \u0631\u0642\u0645 %1 \u0641\u0627\u062a\u0648\u0631\u0629\u061b \u0627\u062d\u0630\u0641 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u0623\u0648\u0644\u0627\u064b","\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0698\u0645\u0627\u0631\u06d5 %1 \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u0647\u06d5\u06cc\u06d5\u061b \u0633\u06d5\u0631\u06d5\u062a\u0627 \u067e\u0633\u0648\u0648\u0644\u06d5\u06a9\u06d5 \u0628\u0633\u0695\u06d5\u0648\u06d5","\u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u0698\u0645\u0627\u0631\u06d5 %1 \u067e\u0633\u0648\u0648\u0644\u06d5 \u0647\u06d5\u06cc\u06d5\u061b \u0626\u06ce\u06a9\u06d5\u0645 \u062c\u0627\u0631 \u067e\u0633\u0648\u0648\u0644\u06ce \u0698\u06ce\u0628\u0628\u06d5"],t.s)
B.aWc=s(["\u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u0644\u0646\u0641\u0633 \u0632\u0628\u0648\u0646 \u0623\u0648 \u0645\u0648\u0631\u062f \u0627\u0644\u0637\u0644\u0628 \u0631\u0642\u0645 %1","\u067e\u0633\u0648\u0648\u0644\u06d5\u06a9\u06d5 \u062f\u06d5\u0628\u06ce\u062a \u0628\u06c6 \u0647\u06d5\u0645\u0627\u0646 \u06a9\u0695\u06cc\u0627\u0631 \u06cc\u0627\u0646 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06cc \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0698\u0645\u0627\u0631\u06d5 %1 \u0628\u06ce\u062a","\u067e\u0633\u0648\u0648\u0644\u06d5 \u062f\u06a4\u06ce\u062a \u0628\u06c6 \u0647\u06d5\u0645\u0627\u0646 \u06a9\u0695\u06cc\u0627\u0631 \u06cc\u0627\u0646 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06ce \u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u0698\u0645\u0627\u0631\u06d5 %1 \u0628\u06cc\u062a"],t.s)
B.b4h=s(["\u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f","\u06af\u06c6\u0695\u06cc\u0646\u06d5\u06a9\u06d5 \u0646\u06d5\u062f\u06c6\u0632\u0631\u0627\u06cc\u06d5\u0648\u06d5","\u06af\u0648\u0647\u06c6\u0695\u06cc\u0646 \u0646\u06d5\u0647\u0627\u062a\u06d5 \u062f\u06cc\u062a\u0646"],t.s)
B.b0d=s(["\u0623\u0636\u0641 \u0645\u0627 \u0627\u0633\u062a\u064f\u0639\u0645\u0644","\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06d5\u06a9\u0627\u0631\u0647\u0627\u062a\u0648\u0648\u06d5 \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5","\u06cc\u0627 \u0647\u0627\u062a\u06cc\u06cc\u06d5 \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u0646 \u0632\u06ce\u062f\u06d5 \u0628\u06a9\u06d5"],t.s)
B.aW8=s(["\u0623\u0636\u0641 \u0645\u0627 \u0635\u064f\u0646\u0639","\u0626\u06d5\u0648\u06d5\u06cc \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0627\u0648\u06d5 \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5","\u06cc\u0627 \u0647\u0627\u062a\u06cc\u06cc\u06d5 \u0686\u06ce\u06a9\u0631\u0646 \u0632\u06ce\u062f\u06d5 \u0628\u06a9\u06d5"],t.s)
B.b2d=s(["\xab%1\xbb \u0644\u0627 \u064a\u0645\u0643\u0646 \u0623\u0646 \u064a\u064f\u0633\u062a\u0639\u0645\u0644 \u0648\u064a\u064f\u0635\u0646\u0639 \u0641\u064a \u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0646\u0641\u0633\u0647","\xab%1\xbb \u0646\u0627\u06a9\u0631\u06ce\u062a \u0644\u06d5 \u06cc\u06d5\u06a9 \u06af\u06c6\u0695\u06cc\u0646\u062f\u0627 \u0647\u06d5\u0645 \u0628\u06d5\u06a9\u0627\u0631\u0628\u06ce\u062a \u0648 \u0647\u06d5\u0645 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u0631\u06ce\u062a","\xab%1\xbb \u0646\u0627\u0628\u06cc\u062a \u062f \u0626\u06ce\u06a9 \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646\u06ce \u062f\u0627 \u0647\u06d5\u0645 \u0628\u0647\u06ce\u062a\u06d5 \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u0646 \u0648 \u0647\u06d5\u0645 \u0628\u0647\u06ce\u062a\u06d5 \u0686\u06ce\u06a9\u0631\u0646"],t.s)
B.b_2=s(["\u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u062d\u0635\u0629 \u0627\u0644\u0643\u0644\u0641\u0629 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0635\u0641\u0631","\u0628\u06d5\u0634\u06cc \u062a\u06ce\u0686\u0648\u0648 \u062f\u06d5\u0628\u06ce\u062a \u0644\u06d5 \u0633\u0641\u0631 \u0632\u06cc\u0627\u062a\u0631 \u0628\u06ce\u062a","\u067e\u0634\u06a9\u0627 \u062a\u06ce\u0686\u0648\u0648\u06cc\u06cc \u062f\u06a4\u06ce\u062a \u0698 \u0633\u0641\u0631\u06ce \u067e\u062a\u0631 \u0628\u06cc\u062a"],t.s)
B.aSs=s(["\u0644\u0627 \u064a\u0645\u0643\u0646 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0623\u062c\u0631\u0629 \u0627\u0644\u0639\u0645\u0644 \u0633\u0627\u0644\u0628\u0629","\u06a9\u0631\u06ce\u06cc \u06a9\u0627\u0631 \u0646\u0627\u06a9\u0631\u06ce\u062a \u0633\u0627\u0644\u0628 \u0628\u06ce\u062a","\u06a9\u0631\u06ce\u06cc\u0627 \u06a9\u0627\u0631\u06cc \u0646\u0627\u0628\u06cc\u062a \u0633\u0627\u0644\u0628 \u0628\u06cc\u062a"],t.s)
B.b5v=s(["\u0627\u062e\u062a\u0631 \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0644\u0644\u0623\u062c\u0631\u0629","\u0626\u06d5\u0648 \u06a9\u0631\u06ce\u06a9\u0627\u0631\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5 \u06a9\u06d5 \u06a9\u0631\u06ce\u06a9\u06d5\u06cc \u0628\u06c6 \u0645\u0627\u0648\u06d5","\u0648\u06cc \u06a9\u0627\u0631\u06a9\u06d5\u0631\u06cc \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5 \u06cc\u06ce \u06a9\u0631\u06ce \u0628\u06c6 \u0645\u0627\u06cc\u06cc"],t.s)
B.aXu=s(["\u0627\u062e\u062a\u0631 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0630\u064a \u062f\u064f\u0641\u0639\u062a \u0645\u0646\u0647 \u0627\u0644\u0623\u062c\u0631\u0629","\u0626\u06d5\u0648 \u0633\u0646\u062f\u0648\u0642\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5 \u06a9\u06d5 \u06a9\u0631\u06ce\u06a9\u06d5\u06cc \u0644\u06ce \u062f\u0631\u0627\u0648\u06d5","\u0648\u06cc \u0633\u0646\u062f\u0648\u0642\u06cc \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5 \u06cc\u06ce \u06a9\u0631\u06ce \u0698\u06ce \u0647\u0627\u062a\u06cc\u06cc\u06d5 \u062f\u0627\u0646"],t.s)
B.aU5=s(["\u0627\u0644\u0639\u0627\u0645\u0644 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f","\u06a9\u0631\u06ce\u06a9\u0627\u0631\u06d5\u06a9\u06d5 \u0646\u06d5\u062f\u06c6\u0632\u0631\u0627\u06cc\u06d5\u0648\u06d5","\u06a9\u0627\u0631\u06a9\u06d5\u0631 \u0646\u06d5\u0647\u0627\u062a\u06d5 \u062f\u06cc\u062a\u0646"],t.s)
